const items = $input.all();
const seen = new Map();

const clean = (value) =>
  String(value || '').toLowerCase().trim().replace(/\s+/g, ' ');

for (const item of items) {
  const lead = item.json;
  const name = clean(lead.business_name);
  const address = clean(lead.address);
  const phone = String(lead.phone || '').replace(/\D/g, '');
  const city = clean(lead.city);

  const key = address
    ? `${name}||${address}`
    : phone
      ? `${name}||${phone}`
      : `${name}||${city}`;

  if (!seen.has(key)) {
    seen.set(key, item);
  } else {
    const existing = seen.get(key);

    if (lead.source === 'gmb' && existing.json.source !== 'gmb') {
      seen.set(key, item);
    }
  }
}

return Array.from(seen.values());

const cfg = $('Set From Webhook').first().json;
const campaignId = $('Postgres — Create Campaign1').first().json.id;
const sources = cfg.source === 'both' ? ['yelp', 'gmb'] : [cfg.source];

return sources.map((active_source) => ({
  json: {
    ...cfg,
    campaign_id: campaignId,
    active_source,
  },
}));

const cfg = $('Code — Expand Sources1').item.json;
const businesses = $input.first().json.businesses || [];

if (!businesses.length) return [];

return businesses.map((b) => ({
  json: {
    external_id: `yelp_${b.id}`,
    source: 'yelp',
    business_name: b.name || '',
    category: (b.categories || []).map((c) => c.title).join(', '),
    phone: b.display_phone || b.phone || '',
    address: (b.location?.display_address || []).join(', '),
    city: b.location?.city || cfg.city,
    state: b.location?.state || '',
    country: b.location?.country || cfg.country,
    website_url: b.url || '',
    rating: b.rating ?? null,
    review_count: b.review_count ?? null,
    status: b.url ? 'new' : 'no_website',
    failure_reason: b.url ? null : 'No website URL found in Yelp listing',
    search_query: cfg.search_query,
    campaign_id: cfg.campaign_id,
    yelp_id: b.id,
  },
}));

const cfg = $('Code — Expand Sources1').first().json;
const limit = Number(cfg.limit) || 10;


const pages = $input.all();
const allPlaces = pages.flatMap((item) =>
  Array.isArray(item.json.places) ? item.json.places : []
);

// Google place ID ke through duplicates remove karo
const seenIds = new Set();
const places = allPlaces.filter((place) => {
  const id = String(place.id || '').replace('places/', '');

  if (!id || seenIds.has(id)) {
    return false;
  }

  seenIds.add(id);
  return true;
});

// User ki requested limit pagination ke baad apply karo
return places.slice(0, limit).map((p) => {
  const rawId = String(p.id || '').replace('places/', '');
  const website = String(p.websiteUri || '').trim();
  const hasWebsite = website.length > 0;

  return {
    json: {
      external_id: `gmb_${rawId}`,
      source: 'gmb',
      business_name: p.displayName?.text || '',
      category: p.primaryType || '',
      phone: p.nationalPhoneNumber || '',
      address: p.formattedAddress || '',
      city: cfg.city || '',
      state: '',
      country: cfg.country || 'AU',
      website_url: website,
      google_url: rawId
        ? `https://www.google.com/maps/place/?q=place_id:${rawId}`
        : '',
      rating: p.rating ?? null,
      review_count: p.userRatingCount ?? null,
      search_query: cfg.search_query || '',
      campaign_id: cfg.campaign_id,
      status: hasWebsite ? 'new' : 'no_website',
      failure_reason: hasWebsite
        ? null
        : 'No website URL in Google Maps listing',
    },
  };
});

const cfg = $('Set From Webhook').first().json;
const campaignId = $('Postgres — Create Campaign1').first().json.id;
const leads = $('Code — Deduplicate').all();

let rawCount = 0;
try { rawCount += $('Code — Normalize GMB1').all().length; } catch(e) {}
try { rawCount += $('Code — Normalize Yelp1').all().length; } catch(e) {}

const startedAt = cfg.started_at
  ? new Date(cfg.started_at).getTime()
  : Date.now();

return [{
  json: {
    campaign_id: campaignId,
    leads_found: rawCount,
    leads_processed: leads.length,
    leads_failed: Math.max(0, rawCount - leads.length),
    duration_ms: Date.now() - startedAt,
    notes: `WF1 lead_generation | ${cfg.search_query} | source=${cfg.source}`,
  },
}];
